/*
 * Flag payload.
 *
 * The table holds the flag text in plaintext, generated by tools/mkflag.py and
 * zeroed again after the build.  Only the station build carries it; the player
 * build ships the same table zeroed.  The table always holds FLAG_MAX bytes so
 * the redacted build and the station build keep an identical layout.
 */
#ifndef PWNCHUCK_FLAG_H
#define PWNCHUCK_FLAG_H

#include "types.h"

#define FLAG_MAX 128

/* True when this build carries a payload (the distributed build does not). */
bool flag_available(void);

/* Decode on demand; the returned pointer stays valid until flag_wipe(). */
const char *flag_text(void);

/* Scrub the decoded text.  Called as soon as room -1 leaves the screen. */
void flag_wipe(void);

#endif
